"""Tests for ChromaScheme canonical schemas and the colour_schema_validator."""
from __future__ import annotations

import sys
from pathlib import Path

import yaml
import pytest

# Add validators directory so colour_schema_validator is importable directly
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "Projects" / "Tooling" / "validators"))
import colour_schema_validator as validator


def _prismata_root() -> str:
    return str(Path(__file__).resolve().parent.parent)


# ---------------------------------------------------------------------------
# chromascheme.output.schema
# ---------------------------------------------------------------------------

def test_valid_chromascheme_output():
    root = _prismata_root()
    instance = {
        "colourSet": [
            {"id": "c0", "origin": "base", "rgb": {"r": 255, "g": 120, "b": 200}},
        ],
        "roles": {
            "primary_surface": {"layers": {"bg": {"colourRef": "c0"}}},
        },
        "geometry": {
            "baseGeometry": "quadratic",
            "overlays": [{"type": "harmonic", "params": {"rotation": 45}}],
        },
    }
    errs = validator.validate_chromascheme_output(instance, root)
    assert errs == [], f"Unexpected errors: {errs}"


def test_chromascheme_output_missing_required():
    root = _prismata_root()
    # Missing 'geometry'
    instance = {
        "colourSet": [{"id": "c0", "rgb": {"r": 0, "g": 0, "b": 0}}],
        "roles": {},
    }
    errs = validator.validate_chromascheme_output(instance, root)
    assert len(errs) >= 1


def test_chromascheme_output_missing_colour_id():
    root = _prismata_root()
    instance = {
        "colourSet": [
            # Missing 'id' — violates required: [id, rgb]
            {"origin": "base", "rgb": {"r": 0, "g": 0, "b": 0}},
        ],
        "roles": {},
        "geometry": {"baseGeometry": "quadratic", "overlays": []},
    }
    errs = validator.validate_chromascheme_output(instance, root)
    assert len(errs) >= 1


# ---------------------------------------------------------------------------
# colour.roles.schema
# ---------------------------------------------------------------------------

def test_valid_colour_roles():
    root = _prismata_root()
    instance = {
        "roles": {
            "primary_surface": {"layers": {"bg": {"colourRef": "c0"}}},
            "border_fg": {"layers": {"fg": {"colourRef": "c4"}}},
        }
    }
    errs = validator.validate_colour_roles(instance, root)
    assert errs == [], f"Unexpected errors: {errs}"


def test_colour_roles_empty_is_valid():
    root = _prismata_root()
    # No required fields at the top level
    errs = validator.validate_colour_roles({}, root)
    assert errs == []


# ---------------------------------------------------------------------------
# colour.preview.multipane.schema
# ---------------------------------------------------------------------------

def test_valid_multipane_preview():
    root = _prismata_root()
    instance = {
        "panes": [
            {
                "role": "primary_surface",
                "layers": {"bg": {"colourRef": "c0"}},
                "fractalPosition": "Q1",
                "proportion": 0.5,
            },
            {
                "role": "secondary_surface",
                "layers": {"bg": {"colourRef": "c1"}, "border": {"colourRef": "c4"}},
                "fractalPosition": "Q2",
                "proportion": 0.5,
            },
        ]
    }
    errs = validator.validate_multipane_preview(instance, root)
    assert errs == [], f"Unexpected errors: {errs}"


def test_multipane_preview_invalid_fractal_position():
    root = _prismata_root()
    instance = {
        "panes": [
            {
                "role": "primary_surface",
                "layers": {},
                "fractalPosition": "Q99",  # not in enum
                "proportion": 0.5,
            }
        ]
    }
    errs = validator.validate_multipane_preview(instance, root)
    assert len(errs) >= 1


def test_multipane_preview_proportion_out_of_range():
    root = _prismata_root()
    instance = {
        "panes": [
            {
                "role": "primary_surface",
                "layers": {},
                "fractalPosition": "Q1",
                "proportion": 1.5,  # > 1
            }
        ]
    }
    errs = validator.validate_multipane_preview(instance, root)
    assert len(errs) >= 1


def test_multipane_preview_pane_missing_required():
    root = _prismata_root()
    instance = {
        "panes": [
            # Missing 'role', 'fractalPosition', 'proportion'
            {"layers": {"bg": {"colourRef": "c0"}}},
        ]
    }
    errs = validator.validate_multipane_preview(instance, root)
    assert len(errs) >= 1


# ---------------------------------------------------------------------------
# Sample instance round-trip
# ---------------------------------------------------------------------------

def test_sample_scheme_loads_and_validates():
    root = _prismata_root()
    sample_path = (
        Path(root) / "Meta" / "canonical" / "colour" / "samples" / "quadratic-4-8.scheme.yaml"
    )
    with open(sample_path, "r", encoding="utf-8") as fh:
        instance = yaml.safe_load(fh)

    errs = validator.validate_chromascheme_output(instance, root)
    assert errs == [], f"Sample failed validation: {errs}"
